Examples
---
## Operator->*
```cpp
// Default ->*:
struct Thing {
    int x = 1234;
    int z = 123;
};
int main() {
    // &Thing::x generates an "Offset" (e.g., "the variable at byte 0").
    // We store this blueprint in 'memberPtr'. Note it doesn't have a value yet.
int Thing::*memberPtr = &Thing::x; // We use :: because it is a member of Thing (it adds a member inside thing) and points to Thing::x.
Thing* thingy = new Thing();
    // The ->* operator combines the INSTANCE (thingy) with the BLUEPRINT (memberPtr).
    // It's like saying: "Go to the 'thingy' address and look at the 'x' offset."
int value = thingy->*memberPtr; // 1234
}
// With a operator->*
#include <iostream>
struct Player {
    int health = 100;
    int mana = 50;
};
template <typename T>
class SmartPtr {
    T* ptr;
public:
    SmartPtr(T* p) : ptr(p) {}
    ~SmartPtr() { delete ptr; }
    T* operator->() { return ptr; }
    // It takes the "offset" (mem) and applies it to the internal raw pointer
    template <typename R>
    R& operator->*(R T::*mem) {
        return ptr->*mem; 
    }
};
int main() {
SmartPtr<Player> hero(new Player());
    int Player::*statPtr = &Player::mana;
    // Without the overload, this line would be a compiler error.
    int value = hero->*statPtr; 
    std::cout << "Mana is: " << value << '\n'; // Prints 50
}
```
```cpp
// Operator comma
#include <iostream>
#include <vector>
struct Pack {
    std::vector<int> numbers;
    // It takes 'this' on the left and an 'int' on the right
    Pack& operator,(int val) {
        numbers.push_back(val);
        return *this; // Return itself so we can keep adding commas
    }
};
int main() {
    Pack p;
    // This looks like magic, but it's just calling operator, repeatedly
    p, 10, 20, 30, 40;
    for (int n : p.numbers) {
        std::cout << n << " "; // Prints 10 20 30 40
    }
}
```
